const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Marovoay location (town in Madagascar)
  const marovoay = ee.Geometry.Point([46.6333, -16.1000]).buffer(5000); // 5km buffer around town

  // Date ranges (±3 days for better image availability)
  const date1_start = '2017-01-15';
  const date1_end = '2017-01-21';
  const date2_start = '2020-01-24';
  const date2_end = '2020-01-30';

  // Get Sentinel-1 data for 2017
  let col1 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(marovoay)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));

  const size1 = await col1.size().getInfo();
  console.log(`2017 Images found: ${size1}`);

  if (size1 === 0) {
    console.log('No Sentinel-1 data for Jan 2017');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get Sentinel-1 data for 2020
  let col2 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(marovoay)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));

  const size2 = await col2.size().getInfo();
  console.log(`2020 Images found: ${size2}`);

  if (size2 === 0) {
    console.log('No Sentinel-1 data for Jan 2020');
    console.log('<answer>C1</answer>');
    return;
  }

  // Process 2017 data
  const img1 = col1.select('VV').median();
  const water1 = img1.lt(-15); // Water threshold

  const stats1 = await water1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: marovoay,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1 = stats1.VV;

  if (waterPixels1 === null || waterPixels1 === undefined) {
    console.log('Calculation failed for 2017');
    console.log('<answer>C3</answer>');
    return;
  }

  // Process 2020 data
  const img2 = col2.select('VV').median();
  const water2 = img2.lt(-15);

  const stats2 = await water2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: marovoay,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2 = stats2.VV;

  if (waterPixels2 === null || waterPixels2 === undefined) {
    console.log('Calculation failed for 2020');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Jan 2017 water pixels: ${waterPixels1}`);
  console.log(`Jan 2020 water pixels: ${waterPixels2}`);

  const waterArea1 = waterPixels1 * 1000 * 1000 / 1e6; // km²
  const waterArea2 = waterPixels2 * 1000 * 1000 / 1e6; // km²

  console.log(`Jan 2017 water extent: ${waterArea1.toFixed(2)} km²`);
  console.log(`Jan 2020 water extent: ${waterArea2.toFixed(2)} km²`);

  if (waterPixels2 > waterPixels1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
